```js
function render() {
  var list = document.querySelector('.todo-list');
  var main = document.querySelector('#main');
  var footer = document.querySelector('#footer');
  var count = document.querySelector('.todo-count');
  var clearBtn = document.querySelector('.clear-completed');
  var toggleAll = document.querySelector('#toggle-all');

  var visible = todos.filter(function(t){
    if (filter === 'active') return !t.completed;
    if (filter === 'completed') return t.completed;
    return true;
  });

  // toggle main/footer
  if (todos.length === 0) {
    main.style.display = 'none';
    footer.style.display = 'none';
  } else {
    main.style.display = '';
    footer.style.display = '';
  }

  // list
  list.innerHTML = '';
  visible.forEach(function(t){
    var li = document.createElement('li');
    li.className = 'todo' + (t.completed ? ' completed' : '');
    li.dataset.id = t.id;
    li.innerHTML = '<div class="view">' +
      '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
      '<label></label>' +
      '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit">';
    li.querySelector('label').textContent = t.title;
    li.querySelector('.edit').value = t.title;
    // hover reveal destroy
    var destroy = li.querySelector('.destroy');
    destroy.style.display = 'none';
    li.addEventListener('mouseenter', function(){ destroy.style.display = 'block'; });
    li.addEventListener('mouseleave', function(){ destroy.style.display = 'none'; });
    list.appendChild(li);
  });

  // count
  var activeCount = todos.filter(function(t){return !t.completed;}).length;
  var label = activeCount === 1 ? 'item' : 'items';
  count.innerHTML = '<strong>' + activeCount + '</strong> ' + label + ' left';

  // clear-completed
  var completedCount = todos.filter(function(t){return t.completed;}).length;
  clearBtn.style.display = completedCount > 0 ? '' : 'none';

  // toggle-all
  toggleAll.checked = todos.length > 0 && completedCount === todos.length;

  // filters selected
  var links = document.querySelectorAll('.filters a');
  links.forEach(function(a){
    var isSel = (a.getAttribute('href') === '#/' && filter === 'all') ||
                (a.getAttribute('href') === '#/active' && filter === 'active') ||
                (a.getAttribute('href') === '#/completed' && filter === 'completed');
    if (isSel) a.classList.add('selected'); else a.classList.remove('selected');
  });
}
```

