// Verification support: happy-dom backed world for the TodoMVC behaviour suite.
// QM-owned. Loads the product template into a real DOM realm and drives it
// through public seams, exactly as a browser would.
const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const TEMPLATE = fs
  .readFileSync(path.join(__dirname, '..', '..', 'assets', 'app-template.index.html'), 'utf8')
  .replace(/<script[\s\S]*?<\/script>/gi, '');

const APP_CODE = fs.readFileSync(path.join(__dirname, '..', '..', 'js', 'app.js'), 'utf8');
const STORE_KEY = 'todos-vanillajs';
const WATCHBILL_PATH = 'watchbill.json';

class AppWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.currentTodoTitle = null;
    this._watchbillBackup = null;
    this.watchbillResult = null;
    this.perturbationResult = null;
  }

  // Boot a fresh DOM realm with the template and the production app evaluated
  // inside the window's own realm, so document/window/localStorage resolve as
  // the globals the app expects.
  loadApp(todos, urlHash) {
    if (this.window && this.window.close) {
      try { this.window.close(); } catch (e) { /* already closed */ }
    }
    const window = new Window({
      url: 'http://localhost/' + (urlHash || ''),
      settings: { disableJavaScriptFileLoading: true, disableJavaScriptEvaluation: true },
    });
    window.document.write(TEMPLATE);
    if (todos && todos.length) {
      window.localStorage.setItem(STORE_KEY, JSON.stringify(todos));
    } else {
      window.localStorage.removeItem(STORE_KEY);
    }
    window.eval(APP_CODE);
    this.window = window;
    this.document = window.document;
  }

  seedAndLoad(rows) {
    const todos = rows.map((r, i) => ({ id: 'seed-' + (i + 1), title: r.title, completed: r.completed }));
    this.loadApp(todos);
  }

  loadEmpty() {
    this.loadApp([]);
  }

  loadSingle(title) {
    this.loadApp([{ id: 'seed-1', title: title, completed: false }]);
  }

  // --- DOM helpers -------------------------------------------------------
  q(sel) {
    return this.document.querySelector(sel);
  }

  ns(sel) {
    return Array.from(this.document.querySelectorAll(sel));
  }

  findTodoLi(title) {
    return this.ns('.todo-list li').find((li) => {
      const label = li.querySelector('label');
      return label && label.textContent === title;
    }) || null;
  }

  // --- interaction helpers ----------------------------------------------
  clickSelector(sel) {
    const el = this.q(sel);
    if (!el) throw new Error('Element not found: ' + sel);
    el.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  clickTodoCheckbox(title) {
    this.currentTodoTitle = title;
    const li = this.findTodoLi(title);
    if (!li) throw new Error('Todo li not found: ' + title);
    li.querySelector('.toggle').dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  doubleClickLabel(title) {
    this.currentTodoTitle = title;
    const li = this.findTodoLi(title);
    if (!li) throw new Error('Todo li not found: ' + title);
    li.querySelector('label').dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  typeAndEnter(selector, text) {
    const el = this.q(selector);
    if (!el) throw new Error('Element not found: ' + selector);
    el.value = text;
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
  }

  setEditValueAndKey(text, key) {
    const li = this.q('.todo-list li.editing');
    if (!li) throw new Error('No todo in editing mode');
    const edit = li.querySelector('.edit');
    edit.value = text;
    const code = key === 'Escape' ? 27 : 13;
    edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: code, bubbles: true }));
  }

  setRoute(hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reload() {
    const raw = this.window.localStorage.getItem(STORE_KEY);
    const todos = raw ? JSON.parse(raw) : [];
    const hash = this.window.location.hash || '';
    this.loadApp(todos, hash);
  }

  removeAllTodos() {
    this.ns('.todo-list li .destroy').forEach((b) =>
      b.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }))
    );
  }

  // --- conformance helpers (verification support only) -------------------
  moveWatchbillAside() {
    if (fs.existsSync(WATCHBILL_PATH)) {
      this._watchbillBackup = '.watchbill.qm.bak';
      fs.renameSync(WATCHBILL_PATH, this._watchbillBackup);
    }
  }

  restoreWatchbill() {
    if (this._watchbillBackup && fs.existsSync(this._watchbillBackup)) {
      fs.renameSync(this._watchbillBackup, WATCHBILL_PATH);
      this._watchbillBackup = null;
    }
  }
}

setWorldConstructor(AppWorld);

// Verification support: step definitions for the TodoMVC suite plus the
// Shipshape methodology conformance checks. QM-owned. Step patterns here are
// the canonical strings referenced verbatim by the @planks annotations in
// js/app.js.
const { Given, When, Then, After } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const STORE_KEY = 'todos-vanillajs';
const WATCHBILL_PATH = 'watchbill.json';
const IMPL_DIRS = ['js'];

// ---------------------------------------------------------------------------
// Methodology conformance checks (verification support, not product behaviour)
// ---------------------------------------------------------------------------
function watchbillShapeCheck() {
  if (!fs.existsSync(WATCHBILL_PATH)) return 'rest';
  let data;
  try {
    data = JSON.parse(fs.readFileSync(WATCHBILL_PATH, 'utf8'));
  } catch (e) {
    return 'violation: invalid JSON';
  }
  const watches = Object.keys(data).filter((k) => /^watch\d+$/.test(k));
  if (watches.length === 0) return 'violation: no watches';
  for (const k of watches) {
    const watch = data[k];
    if (!watch || !Array.isArray(watch.scenarios)) return 'violation: ' + k;
    for (const ref of watch.scenarios) {
      if (typeof ref !== 'string') return 'violation: ' + k + ' entry';
      const isTag = ref.startsWith('@');
      const isRef = /^features\/.*\.feature:/.test(ref);
      if (!isTag && !isRef) return 'violation: ' + ref;
    }
  }
  return 'valid';
}

function walk(dir, cb) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(p, cb);
    else if (entry.isFile()) cb(p);
  }
}

function perturbationQuiescenceCheck() {
  const violations = [];
  for (const dir of IMPL_DIRS) {
    if (!fs.existsSync(dir)) continue;
    walk(dir, (file) => {
      if (fs.readFileSync(file, 'utf8').includes('PERTURBATION')) violations.push(file);
    });
  }
  return violations;
}

