/* TodoMVC — vanilla JS, no preprocessors.
 * Loaded into a happy-dom window realm during verification (window.eval), so
 * document/window/localStorage resolve as the globals the app expects.
 * Every behaviour-bearing seam carries a @planks annotation naming the exact
 * step-definition pattern it satisfies (see features/support/steps.js).
 */
var ENTER_KEY = 13;
var ESCAPE_KEY = 27;
var STORE_KEY = 'todos-vanillajs';

/** @planks("the app loads with todo {string}") */
function createTodo(title) {
  return { id: uid(), title: title, completed: false };
}

/** @planks("the app loads with todos:") */
/** @planks("the page is reloaded") */
function loadTodos() {
  try {
    return JSON.parse(window.localStorage.getItem(STORE_KEY)) || [];
  } catch (e) {
    return [];
  }
}

/** @planks("localStorage {string} contains a todo with title {string}") */
function saveTodos(todos) {
  window.localStorage.setItem(STORE_KEY, JSON.stringify(todos));
}

var filter = 'all';

/** @planks("the route is {string}") */
function setFilterFromHash() {
  var hash = window.location.hash;
  if (hash === '#/active') filter = 'active';
  else if (hash === '#/completed') filter = 'completed';
  else filter = 'all';
}

/** @planks("{string} is typed into {string} and Enter is pressed") */
function addTodo(title) {
  todos.push(createTodo(title));
  saveTodos(todos);
  render();
}

/** @planks("the {string} todo checkbox is clicked") */
/** @planks("the {string} todo is marked active") */
/** @planks("its model {string} is {string}") */
function toggleTodo(id) {
  todos.forEach(function (t) {
    if (t.id === id) t.completed = !t.completed;
  });
  saveTodos(todos);
  render();
}

/** @planks("{string} is clicked") */
function toggleAll(checked) {
  todos.forEach(function (t) {
    t.completed = checked;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} label is double-clicked") */
/** @planks("its {string} input is focused") */
/** @planks("localStorage {string} does not record the {string} state") */
function enterEditMode(li) {
  li.classList.add('editing');
  var edit = li.querySelector('.edit');
  edit.focus();
}

/** @planks(".edit is set to {string} and Enter is pressed") */
/** @planks("the {string} todo is renamed to {string}") */
function commitEdit(edit) {
  var li = edit.closest('li');
  var id = li.dataset.id;
  var value = edit.value.trim();
  li.classList.remove('editing');
  if (!value) {
    removeTodo(id);
  } else {
    todos.forEach(function (t) {
      if (t.id === id) t.title = value;
    });
    saveTodos(todos);
    render();
  }
}

/** @planks(".edit is set to {string} and Escape is pressed") */
/** @planks("the {string} todo is still named {string}") */
function cancelEdit(edit) {
  var li = edit.closest('li');
  li.classList.remove('editing');
  edit.value = edit.dataset.title || edit.value;
  edit.blur();
}

/** @planks("the {string} todo is destroyed") */
/** @planks("only the {string} todo remains") */
function removeTodo(id) {
  todos = todos.filter(function (t) {
    return t.id !== id;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} button is clicked") */
function clearCompleted() {
  todos = todos.filter(function (t) {
    return !t.completed;
  });
  saveTodos(todos);
  render();
}

/** @planks("the {string} \".destroy\" button is hidden until the todo is hovered") */
function attachHover(li, destroy) {
  destroy.style.display = 'none';
  li.addEventListener('mouseenter', function () {
    destroy.style.display = 'block';
  });
  li.addEventListener('mouseleave', function () {
    destroy.style.display = 'none';
  });
}

/** @planks("#main section is hidden") */
/** @planks("#footer section is hidden") */
/** @planks("the todo count is {int}") */
/** @planks("the {string} shows {string}") */
/** @planks("the {string} button is visible") */
/** @planks("the {string} button is hidden") */
/** @planks("every todo has class {string}") */
/** @planks("#toggle-all is unchecked") */
/** @planks("#toggle-all is checked") */
/** @planks("the {string} todo has class {string}") */
/** @planks("only active todos are shown") */
/** @planks("only completed todos are shown") */
/** @planks("all todos are shown") */
/** @planks("the {string} filter link has class {string}") */
/** @planks("a todo {string} exists in {string}") */
function render() {
  var list = document.querySelector('.todo-list');
  var main = document.querySelector('#main');
  var footer = document.querySelector('#footer');
  var count = document.querySelector('.todo-count');
  var clearBtn = document.querySelector('.clear-completed');
  var toggleAllEl = document.querySelector('#toggle-all');

  var visible = todos.filter(function (t) {
    if (filter === 'active') return !t.completed;
    if (filter === 'completed') return t.completed;
    return true;
  });

  main.style.display = todos.length === 0 ? 'none' : '';
  footer.style.display = todos.length === 0 ? 'none' : '';

  list.innerHTML = '';
  visible.forEach(function (t) {
    var li = document.createElement('li');
    li.dataset.id = t.id;
    li.className = t.completed ? 'completed' : '';
    li.innerHTML =
      '<div class="view">' +
      '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
      '<label></label>' +
      '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit">';
    li.querySelector('label').textContent = t.title;
    var edit = li.querySelector('.edit');
    edit.value = t.title;
    edit.dataset.title = t.title;
    attachHover(li, li.querySelector('.destroy'));
    list.appendChild(li);
  });

  var activeCount = todos.filter(function (t) {
    return !t.completed;
  }).length;
  var labelWord = activeCount === 1 ? 'item' : 'items';
  count.innerHTML = '<strong>' + activeCount + '</strong> ' + labelWord + ' left';

  var completedCount = todos.length - activeCount;
  clearBtn.style.display = completedCount > 0 ? '' : 'none';

  toggleAllEl.checked = todos.length > 0 && completedCount === todos.length;

  var links = document.querySelectorAll('.filters a');
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    var href = a.getAttribute('href');
    var selected =
      (href === '#/' && filter === 'all') ||
      (href === '#/active' && filter === 'active') ||
      (href === '#/completed' && filter === 'completed');
    if (selected) a.classList.add('selected');
    else a.classList.remove('selected');
  }
}

/** @planks("the app has loaded") */
/** @planks(".new-todo has focus") */
function init() {
  var main = document.querySelector('.main');
  if (main && !main.id) main.id = 'main';
  var footer = document.querySelector('.footer');
  if (footer && !footer.id) footer.id = 'footer';

  todos = loadTodos();
  setFilterFromHash();
  render();
  var input = document.querySelector('.new-todo');
  if (input) input.focus();

  var newTodo = document.querySelector('.new-todo');
  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      var value = newTodo.value.trim();
      if (value) {
        addTodo(value);
        newTodo.value = '';
      }
    }
  });

  document.addEventListener('click', function (e) {
    var toggle = e.target.closest('.toggle');
    if (toggle) {
      toggleTodo(toggle.closest('li').dataset.id);
      return;
    }
    var destroy = e.target.closest('.destroy');
    if (destroy) {
      removeTodo(destroy.closest('li').dataset.id);
      return;
    }
    if (e.target.classList.contains('clear-completed')) {
      clearCompleted();
      return;
    }
    if (e.target.id === 'toggle-all') {
      toggleAll(e.target.checked);
      return;
    }
  });

  document.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (label) {
      enterEditMode(label.closest('li'));
    }
  });

  document.addEventListener('keydown', function (e) {
    var edit = e.target;
    if (!edit.classList || !edit.classList.contains('edit')) return;
    if (e.keyCode === ENTER_KEY) {
      commitEdit(edit);
    } else if (e.keyCode === ESCAPE_KEY) {
      cancelEdit(edit);
    }
  });

  document.addEventListener(
    'blur',
    function (e) {
      var edit = e.target;
      if (!edit.classList || !edit.classList.contains('edit')) return;
      var li = edit.closest('li');
      if (li && li.classList.contains('editing')) {
        commitEdit(edit);
      }
    },
    true
  );

  window.addEventListener('hashchange', function () {
    setFilterFromHash();
    render();
  });
}

function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

var todos = [];
init();

