  const cells = line.split("│");
  const raw = cells[1] || "";
  const afterSep = raw.replace(/^ /, "");      // drop the single │-separator space
  if (/^\s/.test(afterSep)) continue;            // example row is further indented
  const pattern = afterSep.replace(/\s+$/, "");
  if (pattern) patterns.add(pattern);
}
const appjs = fs.readFileSync("js/app.js","utf8");
