let stale = 0;
for (const p of planks) {
  if (!patterns.has(p)) { console.log("STALE:", p); stale++; }
}
console.log(stale === 0 ? "JOIN OK: every plank matches a step-usage pattern" : ("STALE COUNT: " + stale));
